#include <stdio.h>
#include <stdlib.h>

void bubble_sort(int *arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (arr[j] > arr[j + 1]) {
                int tmp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = tmp;
            }
        }
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    int *arr = malloc(sizeof(int) * (size_t)n);
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &arr[i]) != 1) return 1;
    }

    bubble_sort(arr, n);

    /* O(n^2) dedup: keep an array of uniques, check membership by scanning it */
    int *uniq = malloc(sizeof(int) * (size_t)n);
    int ucount = 0;
    for (int i = 0; i < n; i++) {
        int found = 0;
        for (int j = 0; j < ucount; j++) {
            if (uniq[j] == arr[i]) { found = 1; break; }
        }
        if (!found) uniq[ucount++] = arr[i];
    }

    for (int i = 0; i < ucount; i++) {
        printf("%d", uniq[i]);
        if (i != ucount - 1) printf(" ");
    }
    printf("\n");

    free(arr);
    free(uniq);
    return 0;
}
